--- 根据传入的道具Id列表刷新Id显示，如果列表为空则显示“无”的提示
---@param itemDatas PbrItem[]
function XUiPBRShopNewPanelSkill:RefreshItemShow(itemDatas)
    self:HideAllGridSkillItems()

    if not XTool.IsTableEmpty(itemDatas) then
        for index = 1, ConstSkillSlotCount do
            local emptyGo = self.EmptyUiList[index]

            local itemData = itemDatas[index]

            if itemData then
                emptyGo.gameObject:SetActiveEx(false)

                local slot = self.GridSlotUiList[index]

                if slot then
                    local itemCfg = self._Control:GetPBRItemCfgById(itemData.ItemId)

                    if itemCfg then
                        local grid = self:GetGridSkillByColor(itemCfg.OrbColor)

                        if grid then
                            grid.Transform:SetParent(slot.transform)
                            grid.Transform:SetAnchoredPosition(0, 0)
                            grid:Open()
                            grid:UpdateItem(itemData)
                        end
                    end
                end
            else
                emptyGo.gameObject:SetActiveEx(true)
            end
        end
    else
        -- 全显示空
        for index = 1, ConstSkillSlotCount do
            local emptyGo = self.EmptyUiList[index]

            if emptyGo then
                emptyGo.gameObject:SetActiveEx(true)
            end
        end
    end
end

function XUiPBRShopNewPanelSkill:HideAllGridSkillItems()
    if not XTool.IsTableEmpty(self.Color2GridSkillItem) then
        for i, v in pairs(self.Color2GridSkillItem) do
            v:Close()
        end
    end
end

